<section class="section section-light"><div class="container"><form class="dealer-search" action="<?= url('dealers') ?>"><input type="hidden" name="lang" value="<?= language() ?>"><div><label for="region"><?= t('Region / State','တိုင်းဒေသကြီး / ပြည်နယ်') ?></label><select name="region" id="region"><option value=""><?= t('All regions','ဒေသအားလုံး') ?></option><?php foreach($regions as $r): ?><option <?= $region===$r['region']?'selected':'' ?> value="<?= e($r['region']) ?>"><?= e($r['region']) ?></option><?php endforeach; ?></select></div><div><label for="location"><?= t('City / township','မြို့ / မြို့နယ်') ?></label><input name="q" id="location" value="<?= e($q) ?>" placeholder="<?= t('Enter your location','သင့်တည်နေရာ ဖြည့်ပါ') ?>"></div><button class="btn btn-primary"><?= t('Search','ရှာရန်') ?></button><a class="text-link" href="<?= site_url('dealers') ?>"><?= t('Reset','ပြန်စရန်') ?></a></form><div class="results-line"><span><?= count($dealers) ?> <?= t('dealers found','ဦး တွေ့ရှိသည်') ?></span></div><div class="contact-grid"><?php foreach($dealers as $dealer): ?><article class="contact-card"><span class="eyebrow"><?= e($dealer['region'].' / '.$dealer['city']) ?></span><h2><?= e(localized($dealer,'title')) ?></h2><p><?= e(localized($dealer,'description')) ?></p><p><?= nl2br(e($dealer['address'])) ?><br><?= e($dealer['township']) ?></p><?php if($dealer['phone']): ?><a href="tel:<?= e(preg_replace('/[^+0-9]/','',$dealer['phone'])) ?>"><?= e($dealer['phone']) ?></a><?php endif; ?><?php if($dealer['map_url']): ?><div><a href="<?= e($dealer['map_url']) ?>" target="_blank" rel="noopener noreferrer"><?= t('View on Google Maps','Google Maps တွင်ကြည့်ရန်') ?> ↗</a></div><?php endif; ?></article><?php endforeach; ?></div><?php if(!$dealers): ?><div class="empty"><h2><?= t('No dealer listings found.','ဒီလာစာရင်း မတွေ့ရှိပါ။') ?></h2><p><?= t('Our directory is being updated. Send us your location for assistance finding SUPERKING products.','ဒီလာစာရင်းကို ပြင်ဆင်နေပါသည်။ SUPERKING ပစ္စည်းများ ရှာဖွေရန် သင့်တည်နေရာဖြင့် ဆက်သွယ်ပါ။') ?></p><a class="btn btn-primary" href="<?= site_url('contact') ?>"><?= t('Ask our team','မေးမြန်းရန်') ?> ↗</a></div><?php endif; ?></div></section>